INSERT INTO sanpham (id, tensanpham, mota, giagoc, giaban, soluongton, hinhanh, danhmuc_id, thuonghieu_id, doituong, sizes, mausac, chatlieu, thanhphan, muctieu, hansudung, noibat, trangthai, luotxem, luotmua) VALUES
(8, 'Áo Thun Tập Gym Nam Under Armour Tech 2.0', 'Áo cổ tròn tay ngắn, vải mềm khô nhanh, không có đường may ở vai nên ít cọ xát khi nâng tạ.', 650000, 520000, 45, 'ao_nam_ua_tech.jpg', 1, 5, 'nam', 'S,M,L,XL', 'Đen,Xám,Xanh Navy', '100% Polyester', NULL, 'tangcan,duytri', NULL, 0, 1, 236, 86),
(9, 'Áo Tank Top Gym Nam Gymshark Critical', 'Áo ba lỗ khoét nách rộng, để lộ vai và lưng khi tập Push hoặc Pull.', 480000, 390000, 50, 'ao_nam_gymshark_tank.jpg', 1, 1, 'nam', 'S,M,L,XL', 'Đen,Trắng,Xám Đậm', 'Cotton pha Polyester', NULL, 'tangcan,duytri', NULL, 0, 1, 133, 32),
(10, 'Áo Thun Tập Luyện Nam Adidas Aeroready', 'Áo thun công nghệ Aeroready thấm hút mồ hôi, form regular, hợp tập cardio và tập tạ nhẹ.', 590000, 450000, 55, 'ao_nam_adidas_aeroready.jpg', 1, 6, 'nam', 'S,M,L,XL', 'Đen,Xanh Than,Xám', '100% Polyester tái chế', NULL, 'giamcan,duytri', NULL, 0, 1, 125, 29),
(11, 'Áo Bra Tập Gym Nữ Nike Pro Indy', 'Áo bra đỡ ngực mức nhẹ, dây đeo chéo lưng, hợp Yoga, Pilates và tập cường độ thấp đến vừa.', 790000, 650000, 40, 'bra_nu_nike_indy.jpg', 1, 2, 'nu', 'S,M,L,XL', 'Đen,Hồng Phấn,Trắng', 'Polyester Dri-FIT pha Spandex', NULL, 'giamcan,duytri', NULL, 1, 1, 86, 29),
(12, 'Áo Croptop Tập Gym Nữ Gymshark Training', 'Áo croptop ôm sát, vải co giãn 4 chiều, không lộ khi cúi người hoặc giơ tay.', 520000, 420000, 38, 'croptop_nu_gymshark.jpg', 1, 1, 'nu', 'S,M,L,XL', 'Đen,Tím,Xanh Mint', 'Nylon pha Elastane', NULL, 'giamcan,duytri', NULL, 0, 1, 117, 42),
(13, 'Quần Short Tập Gym Nam Under Armour Tech', 'Quần short dài trên gối, cạp thun có dây rút, hai túi bên hông.', 520000, 420000, 48, 'quan_nam_ua_short.jpg', 2, 5, 'nam', 'S,M,L,XL', 'Đen,Xám,Xanh Navy', '100% Polyester', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 185, 63),
(14, 'Quần Jogger Tập Gym Nam Nike Dri-FIT', 'Quần jogger bo gấu, vải Dri-FIT dày vừa, hợp tập buổi sáng sớm hoặc tập ở phòng lạnh.', 950000, 790000, 30, 'quan_nam_nike_jogger.jpg', 2, 2, 'nam', 'S,M,L,XL', 'Đen,Xám Đậm', 'Polyester Dri-FIT', NULL, 'tangcan,duytri', NULL, 0, 1, 46, 13),
(15, 'Quần Short Tập Luyện Nam Adidas Designed 4 Training', 'Quần short co giãn nhẹ, cạp thun, có túi khóa kéo phía sau đựng thẻ hoặc chìa khóa.', 650000, 520000, 42, 'quan_nam_adidas_short.jpg', 2, 6, 'nam', 'S,M,L,XL', 'Đen,Xanh Than', 'Polyester tái chế pha Elastane', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 99, 20),
(16, 'Quần Legging Nữ Gymshark Vital Seamless', 'Legging cạp cao dệt liền không đường may, ôm đùi và mông, không xuyên thấu khi Squat.', 1050000, 850000, 36, 'legging_nu_gymshark_vital.jpg', 2, 1, 'nu', 'S,M,L,XL', 'Đen,Hồng Pastel,Xám', 'Nylon pha Elastane', NULL, 'giamcan,duytri', NULL, 1, 1, 126, 49),
(17, 'Quần Legging Nữ Adidas Optime Training', 'Legging cạp cao, có túi nhỏ ở cạp, dùng cho Gym, Yoga và chạy bộ.', 1100000, 890000, 34, 'legging_nu_adidas_optime.jpg', 2, 6, 'nu', 'S,M,L,XL', 'Đen,Xanh Than', 'Polyester tái chế pha Elastane', NULL, 'giamcan,duytri', NULL, 0, 1, 267, 89),
(18, 'Quần Short Tập Gym Nữ Nike Pro 3 Inch', 'Quần short bó dài 3 inch, mặc trong hoặc mặc ngoài, không bị cuộn lên khi tập chân.', 620000, 490000, 40, 'quan_nu_nike_pro_short.jpg', 2, 2, 'nu', 'S,M,L,XL', 'Đen,Xám,Xanh Dương', 'Polyester pha Spandex', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 295, 115),
(19, 'Găng Tay Tập Gym Harbinger Pro Có Quấn Cổ Tay', 'Đệm lòng bàn tay, dây quấn cổ tay cố định khớp khi đẩy ngực, kéo xô và đẩy vai.', 480000, 390000, 45, 'gang_tay_harbinger_pro.jpg', 3, 7, 'unisex', 'S,M,L,XL', 'Đen,Đen Đỏ', 'Da tổng hợp, lưới thoáng, đệm xốp', NULL, 'tangcan,duytri', NULL, 0, 1, 83, 28),
(20, 'Đai Lưng Tập Tạ Harbinger 4 Inch', 'Đai bản rộng 4 inch, khóa dán Velcro, giữ thân người ổn định khi Squat và Deadlift nặng.', 850000, 690000, 25, 'dai_lung_harbinger_4inch.jpg', 3, 7, 'unisex', 'S,M,L,XL', 'Đen', 'Nylon bọc xốp, khóa dán', NULL, 'tangcan,giamcan', NULL, 1, 1, 170, 62),
(21, 'Dây Kéo Lưng Lifting Straps Harbinger', 'Dây quấn cổ tay giúp giữ đòn tạ khi Deadlift và kéo xô mà không phụ thuộc lực nắm.', 250000, 190000, 60, 'day_keo_harbinger.jpg', 3, 7, 'unisex', NULL, 'Đen,Đỏ', 'Cotton bản dày, đệm cổ tay Neoprene', NULL, 'tangcan', NULL, 0, 1, 120, 40),
(22, 'Băng Quấn Gối Harbinger Knee Sleeves', 'Băng gối Neoprene dày 5mm, giữ ấm và hỗ trợ khớp gối khi Squat, Lunge và chạy bộ.', 520000, 420000, 32, 'bang_goi_harbinger.jpg', 3, 7, 'unisex', 'S,M,L,XL', 'Đen', 'Neoprene 5mm', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 196, 42),
(23, 'Bình Lắc BlenderBottle Classic 28oz (820ml)', 'Bình có quả lắc dây thép BlenderBall, nắp vặn có vòng đệm chống rò, có vạch chia ml.', 280000, 220000, 80, 'binh_lac_blender_classic.jpg', 4, 8, 'unisex', NULL, 'Đen,Trong Suốt,Xanh Navy', 'Nhựa Tritan không chứa BPA', NULL, 'giamcan,tangcan,duytri', NULL, 1, 1, 227, 75),
(24, 'Bình Lắc BlenderBottle ProStak 22oz (650ml)', 'Bình có ngăn chứa riêng cho bột hoặc viên, tách ra được, tiện mang khi đi tập.', 420000, 340000, 50, 'binh_lac_blender_prostak.jpg', 4, 8, 'unisex', NULL, 'Đen,Xám', 'Nhựa Tritan không chứa BPA', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 57, 21),
(25, 'Bình Nước Thể Thao MyProtein 1 Lít', 'Bình dung tích 1 lít, nắp bật có khóa, có vạch đo lượng nước uống trong ngày.', 190000, 150000, 70, 'binh_nuoc_myprotein_1l.jpg', 4, 4, 'unisex', NULL, 'Đen,Xanh Dương,Trắng', 'Nhựa PP không chứa BPA', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 201, 53),
(26, 'Khăn Tập Gym Microfiber Gymshark', 'Khăn microfiber khô nhanh, kích thước 40x80cm, có khuy gài để treo vào máy tập.', 220000, 170000, 65, 'khan_tap_gymshark.jpg', 4, 1, 'unisex', NULL, 'Đen,Xám', 'Microfiber', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 75, 19),
(27, 'Túi Trống Tập Gym Under Armour Undeniable Duffle', 'Túi trống có ngăn giày riêng và ngăn ướt, dây đeo vai có đệm, chịu nước nhẹ.', 1200000, 950000, 22, 'tui_trong_ua_duffle.jpg', 4, 5, 'unisex', NULL, 'Đen,Xám Đậm', 'Polyester chống thấm nước', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 165, 54),
(28, 'Whey Protein Dymatize ISO100 Hydrolyzed 5Lbs (2.3kg)', 'Whey thủy phân tách béo và đường, hấp thu nhanh sau tập. Pha 1 muỗng với 200 đến 250ml nước.', 2350000, 2090000, 20, 'whey_dymatize_iso100.jpg', 5, 9, 'unisex', NULL, 'Vị Chocolate,Vị Vani,Vị Dâu', NULL, 'Khoảng 25g Protein, 5g BCAA, dưới 1g đường, khoảng 110 Calories mỗi muỗng (30g)', 'tangcan,duytri', '2028-03-31', 1, 1, 118, 42),
(29, 'Sữa Tăng Cân Optimum Nutrition Serious Mass 12Lbs (5.4kg)', 'Mass Gainer nhiều Calories cho người gầy khó tăng cân. Dùng 1 đến 2 lần mỗi ngày, uống kèm bữa chính.', 1950000, 1690000, 18, 'mass_on_serious_mass.jpg', 5, 3, 'unisex', NULL, 'Vị Chocolate,Vị Vani', NULL, 'Khoảng 1250 Calories, 50g Protein, 250g Carb mỗi 2 muỗng lớn (334g), bổ sung Creatine và vitamin', 'tangcan', '2028-01-31', 0, 1, 290, 107),
(30, 'Whey Protein MyProtein Impact Whey 2.5kg', 'Whey Concentrate giá dễ tiếp cận, dùng 1 muỗng sau tập hoặc giữa các bữa ăn.', 1450000, 1190000, 28, 'whey_myprotein_impact.jpg', 5, 4, 'unisex', NULL, 'Vị Chocolate,Vị Vani,Vị Dâu', NULL, 'Khoảng 21g Protein, 4g BCAA, 103 Calories mỗi muỗng (25g)', 'tangcan,duytri', '2028-02-28', 0, 1, 176, 54),
(31, 'Creatine Monohydrate MuscleTech Platinum 100% 400g', 'Creatine Monohydrate dạng bột không hương vị, dùng 5g mỗi ngày với nước, tăng sức mạnh khi tập nặng.', 690000, 550000, 35, 'creatine_muscletech_400g.jpg', 5, 11, 'unisex', NULL, 'Không Vị', NULL, '5g Creatine Monohydrate mỗi lần dùng, khoảng 80 lần dùng mỗi hộp', 'tangcan,duytri', '2028-06-30', 1, 1, 180, 69),
(32, 'BCAA Applied Nutrition Amino-Hydrate 450g', 'Bột BCAA kèm chất điện giải, uống trong lúc tập để bù nước và hạn chế mất cơ khi giảm mỡ.', 650000, 520000, 30, 'bcaa_applied_amino_hydrate.jpg', 5, 10, 'unisex', NULL, 'Vị Cam,Vị Dưa Hấu,Vị Chanh Dây', NULL, 'BCAA tỉ lệ 2:1:1 (Leucine, Isoleucine, Valine), Glutamine, chất điện giải', 'giamcan,duytri', '2028-04-30', 0, 1, 87, 27),
(33, 'Pre-Workout Applied Nutrition ABE 315g', 'Bột pre-workout chứa Caffeine, Beta-Alanine và Citrulline. Dùng 1 muỗng pha với nước 20 đến 30 phút trước khi tập.', 780000, 650000, 26, 'pre_applied_abe.jpg', 6, 10, 'unisex', NULL, 'Vị Cherry Cola,Vị Táo Xanh', NULL, 'Caffeine, Beta-Alanine, L-Citrulline, Taurine, Vitamin nhóm B', 'tangcan,duytri', '2028-02-29', 1, 1, 118, 39),
(34, 'Hydroxycut Hardcore Elite MuscleTech 100 Viên', 'Viên hỗ trợ đốt mỡ chứa Caffeine, dùng khi tập Cardio hoặc HIIT. Không dùng gần giờ ngủ.', 750000, 620000, 24, 'dotmo_muscletech_hydroxycut.jpg', 6, 11, 'unisex', NULL, 'Hộp 100 viên', NULL, 'Caffeine Anhydrous, chiết xuất trà xanh, L-Theanine', 'giamcan', '2028-05-31', 0, 1, 206, 60),
(35, 'Amino Energy Optimum Nutrition 270g (30 Lần Dùng)', 'Bột Amino kèm Caffeine từ trà xanh và hạt cà phê xanh, dùng trước hoặc trong lúc tập.', 640000, 520000, 33, 'amino_on_energy.jpg', 6, 3, 'unisex', NULL, 'Vị Cam,Vị Dâu,Vị Trái Cây Hỗn Hợp', NULL, 'Khoảng 5g Amino Acid, khoảng 100mg Caffeine mỗi lần dùng (9g)', 'giamcan,duytri', '2028-01-31', 0, 1, 107, 31),
(36, 'Vitamin Tổng Hợp Optimum Nutrition Opti-Men 90 Viên', 'Multivitamin cho nam giới tập luyện, dùng 3 viên mỗi ngày sau bữa ăn.', 690000, 560000, 30, 'vitamin_on_opti_men.jpg', 7, 3, 'nam', NULL, 'Hộp 90 viên', NULL, 'Vitamin A, C, D, E, nhóm B, khoáng chất, hỗn hợp Amino Acid', 'tangcan,duytri', '2028-04-30', 0, 1, 172, 68),
(37, 'Vitamin Tổng Hợp Optimum Nutrition Opti-Women 120 Viên', 'Multivitamin cho nữ giới tập luyện, có Sắt và Canxi, dùng 2 viên mỗi ngày sau bữa ăn.', 640000, 520000, 28, 'vitamin_on_opti_women.jpg', 7, 3, 'nu', NULL, 'Hộp 120 viên', NULL, 'Vitamin A, C, D, E, nhóm B, Sắt, Canxi, Folate', 'giamcan,duytri', '2028-04-30', 0, 1, 155, 47),
(38, 'Omega-3 Now Foods 1000mg 200 Viên', 'Dầu cá chứa EPA và DHA, dùng 1 đến 2 viên mỗi ngày cùng bữa ăn.', 560000, 450000, 40, 'omega3_now_foods.jpg', 7, 12, 'unisex', NULL, 'Hộp 200 viên', NULL, 'Dầu cá (EPA, DHA), Vitamin E', 'giamcan,duytri', '2028-08-31', 0, 1, 164, 35),
(39, 'Vitamin D3 Now Foods 5000 IU 240 Viên', 'Vitamin D3 dạng viên mềm, dùng 1 viên mỗi ngày cùng bữa ăn có chất béo.', 420000, 340000, 40, 'vitamin_d3_now_foods.jpg', 7, 12, 'unisex', NULL, 'Hộp 240 viên', NULL, 'Vitamin D3 (Cholecalciferol) 5000 IU mỗi viên, dầu ô liu', 'tangcan,duytri', '2028-10-31', 0, 1, 109, 27);
